<?php
declare(strict_types=1);
final class WorkService {
    public const GROUPS=['backlog'=>'Backlog','unstarted'=>'To do','started'=>'In progress','completed'=>'Done','cancelled'=>'Cancelled'];
    public const TYPES=['task'=>'Task','bug'=>'Bug','story'=>'Story','epic'=>'Epic','subtask'=>'Subtask'];
    public const PRIORITIES=[0=>'No priority',1=>'Urgent',2=>'High',3=>'Medium',4=>'Low'];
    public const LAYOUTS=['list'=>'List','board'=>'Board','calendar'=>'Calendar','spreadsheet'=>'Spreadsheet','gantt'=>'Timeline'];
    public static function text(mixed $value,int $max=2000,bool $required=false):string{if(!is_string($value)||!mb_check_encoding($value,'UTF-8')||str_contains($value,"\0")||mb_strlen($value)>$max||($required&&trim($value)===''))throw new InvalidArgumentException('Enter valid text within its allowed length.');return trim($value);}
    public static function date(mixed $value):?string{return $value===''||$value===null?null:valid_date(self::text($value,10,true));}
    public static function color(mixed $value):string{$color=self::text($value,7,true);if(!preg_match('/^#[a-fA-F0-9]{6}$/D',$color))throw new InvalidArgumentException('Use a six-digit hex colour.');return $color;}
    public static function markdown(string $source):string {
        $inline=static function(string $line):string {
            $line=e($line);
            $line=preg_replace('/\*\*([^\n]+?)\*\*/u','<strong>$1</strong>',$line)??$line;
            $line=preg_replace('/`([^`\n]+)`/u','<code>$1</code>',$line)??$line;
            $line=preg_replace('/\*([^*\n]+)\*/u','<em>$1</em>',$line)??$line;
            return $line;
        };
        $output='';$list=false;
        foreach(preg_split('/\r\n|\r|\n/',$source) as $line){
            if(preg_match('/^[-*]\s+(.+)$/u',$line,$match)){if(!$list){$output.='<ul>';$list=true;}$output.='<li>'.$inline($match[1]).'</li>';continue;}
            if($list){$output.='</ul>';$list=false;}
            if(preg_match('/^(#{1,3})\s+(.+)$/u',$line,$match)){$level=min(4,strlen($match[1])+1);$output.='<h'.$level.'>'.$inline($match[2]).'</h'.$level.'>';}
            elseif(trim($line)!=='')$output.='<p>'.$inline($line).'</p>';
        }
        return $output.($list?'</ul>':'');
    }
    public static function workspace(int $id):array{return Db::one('SELECT * FROM work_workspaces WHERE id=?',[$id])??throw new InvalidArgumentException('Workspace not found.');}
    public static function workspaces():array{return Db::all('SELECT w.*,(SELECT COUNT(*) FROM work_projects p WHERE p.workspace_id=w.id) projects FROM work_workspaces w ORDER BY archived_at IS NOT NULL,id');}
    public static function self(int $workspace):int{self::workspace($workspace);return (int)(Db::one('SELECT id FROM work_people WHERE workspace_id=? AND is_self=1',[$workspace])['id']??throw new RuntimeException('Workspace owner is missing.'));}
    public static function saveWorkspace(array $data,?int $id=null):int{
        $name=self::text($data['name']??'',120,true);$description=self::text($data['description']??'',3000);
        if($id){self::workspace($id);Db::run('UPDATE work_workspaces SET name=?,description=? WHERE id=?',[$name,$description,$id]);return $id;}
        return Db::tx(function()use($name,$description){$id=Db::run('INSERT INTO work_workspaces(name,description) VALUES (?,?)',[$name,$description]);Db::run('INSERT INTO work_people(workspace_id,name,is_self) VALUES (?,?,1)',[$id,Db::setting('name','You')?:'You']);return $id;});
    }
    public static function people(int $workspace):array{self::workspace($workspace);return Db::all('SELECT * FROM work_people WHERE workspace_id=? ORDER BY active DESC,is_self DESC,name',[$workspace]);}
    public static function person(int $workspace,int $id,bool $active=false):array{$person=Db::one('SELECT * FROM work_people WHERE workspace_id=? AND id=?',[$workspace,$id]);if(!$person||($active&&!(int)$person['active']))throw new InvalidArgumentException('Choose an active assignee from this workspace.');return $person;}
    public static function savePerson(int $workspace,array $data,?int $id=null):int{
        self::workspace($workspace);$name=self::text($data['name']??'',120,true);$email=self::text($data['email']??'',254);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter a valid email or leave it empty.');
        if($id){$person=self::person($workspace,$id);$flag=$data['active']??'1';if(!in_array($flag,['0','1',0,1,false,true],true))throw new InvalidArgumentException('Choose active or inactive.');$active=in_array($flag,['1',1,true],true)?1:0;if($person['is_self']&&!$active)throw new InvalidArgumentException('Keep the workspace owner active.');Db::run('UPDATE work_people SET name=?,email=?,active=? WHERE id=?',[$name,$email,$active,$id]);return $id;}return Db::run('INSERT INTO work_people(workspace_id,name,email) VALUES (?,?,?)',[$workspace,$name,$email]);
    }
    public static function project(int $id):array{return Db::one('SELECT p.*,w.name workspace_name FROM work_projects p JOIN work_workspaces w ON w.id=p.workspace_id WHERE p.id=?',[$id])??throw new InvalidArgumentException('Project not found.');}
    public static function projects(int $workspace,bool $archived=false):array{self::workspace($workspace);return Db::all('SELECT p.*,(SELECT COUNT(*) FROM work_issues i WHERE i.project_id=p.id AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status=\'accepted\') issue_count FROM work_projects p WHERE p.workspace_id=? AND '.($archived?"p.status='archived'":"p.status<>'archived'").' ORDER BY p.updated_at DESC,p.id DESC',[$workspace]);}
    public static function saveProject(int $workspace,array $data,?int $id=null):int{
        $w=self::workspace($workspace);if($w['archived_at']!==null)throw new InvalidArgumentException('Restore this workspace before adding projects.');$name=self::text($data['name']??'',160,true);$identifier=strtoupper(self::text($data['identifier']??'',8,true));if(!preg_match('/^[A-Z][A-Z0-9]{1,7}$/D',$identifier))throw new InvalidArgumentException('Use a project identifier of 2 to 8 uppercase letters/numbers, starting with a letter.');$description=self::text($data['description']??'',10000);$kind=$data['kind']??'personal';if(!in_array($kind,['personal','study','business','client'],true))throw new InvalidArgumentException('Choose a project type.');$start=self::date($data['start_date']??'');$target=self::date($data['target_date']??'');if($start&&$target&&$target<$start)throw new InvalidArgumentException('Target date must be on or after the start date.');$lead=optional_id($data['lead_id']??'');if($lead)self::person($workspace,$lead,true);$website=optional_id($data['website_id']??'');if($website)WebsiteService::profile($website);
        return Db::tx(function()use($workspace,$name,$identifier,$description,$kind,$start,$target,$lead,$website,$id){if(Db::one('SELECT id FROM work_projects WHERE workspace_id=? AND identifier=? AND id<>?',[$workspace,$identifier,$id??0]))throw new InvalidArgumentException('This workspace already uses that project identifier.');
            if($id){$project=self::project($id);if((int)$project['workspace_id']!==$workspace)throw new InvalidArgumentException('Project does not belong to this workspace.');Db::run('UPDATE work_projects SET name=?,identifier=?,description=?,kind=?,lead_id=?,website_id=?,start_date=?,target_date=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$name,$identifier,$description,$kind,$lead,$website,$start,$target,$id]);}
            else{$id=Db::run('INSERT INTO work_projects(workspace_id,name,identifier,description,kind,lead_id,website_id,start_date,target_date) VALUES (?,?,?,?,?,?,?,?,?)',[$workspace,$name,$identifier,$description,$kind,$lead,$website,$start,$target]);$colors=['backlog'=>'#94a3b8','unstarted'=>'#64748b','started'=>'#3b82f6','completed'=>'#22b37e','cancelled'=>'#e17464'];$position=0;foreach(self::GROUPS as $group=>$label)Db::run('INSERT INTO work_states(project_id,name,state_group,color,position) VALUES (?,?,?,?,?)',[$id,$label,$group,$colors[$group],$position++]);}
            self::log($id,null,'project.saved',$name);return $id;});
    }
    public static function archiveProject(int $id,bool $restore=false):void{self::project($id);Db::run('UPDATE work_projects SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$restore?'active':'archived',$id]);self::log($id,null,$restore?'project.restored':'project.archived','');}
    public static function states(int $project):array{self::project($project);return Db::all("SELECT s.*,(SELECT COUNT(*) FROM work_issues i WHERE i.state_id=s.id AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted') active_count FROM work_states s WHERE s.project_id=? ORDER BY s.position,s.id",[$project]);}
    public static function labels(int $project):array{self::project($project);return Db::all('SELECT * FROM work_labels WHERE project_id=? ORDER BY name',[$project]);}
    public static function scoped(string $table,int $project,int $id):array{if(!in_array($table,['work_states','work_labels','work_cycles','work_modules','work_pages','work_views','work_releases'],true))throw new LogicException('Invalid scoped resource.');return Db::one('SELECT * FROM '.$table.' WHERE project_id=? AND id=?',[$project,$id])??throw new InvalidArgumentException('Choose a resource from this project.');}
    public static function saveState(int $project,array $data,?int $id=null):int{self::project($project);$name=self::text($data['name']??'',80,true);$group=$data['state_group']??'';if(!is_string($group)||!isset(self::GROUPS[$group]))throw new InvalidArgumentException('Choose a workflow state group.');$color=self::color($data['color']??'');$position=int_range($data['position']??'0',0,1000);$old=$id?self::scoped('work_states',$project,$id):null;$limitValue=$data['wip_limit']??($old['wip_limit']??'');$limit=$limitValue===''||$limitValue===null?null:int_range($limitValue,1,1000);if(Db::one('SELECT id FROM work_states WHERE project_id=? AND name=? AND id<>?',[$project,$name,$id??0]))throw new InvalidArgumentException('This project already has that workflow state.');if($id){self::scoped('work_states',$project,$id);Db::run('UPDATE work_states SET name=?,state_group=?,color=?,position=?,wip_limit=? WHERE id=?',[$name,$group,$color,$position,$limit,$id]);self::snapshot($project);self::log($project,null,'workflow.updated',$name);return $id;}return Db::run('INSERT INTO work_states(project_id,name,state_group,color,position,wip_limit) VALUES (?,?,?,?,?,?)',[$project,$name,$group,$color,$position,$limit]);}
    public static function saveLabel(int $project,array $data,?int $id=null):int{self::project($project);$name=self::text($data['name']??'',80,true);$color=self::color($data['color']??'');if(Db::one('SELECT id FROM work_labels WHERE project_id=? AND name=? AND id<>?',[$project,$name,$id??0]))throw new InvalidArgumentException('This project already has that label.');if($id){self::scoped('work_labels',$project,$id);Db::run('UPDATE work_labels SET name=?,color=? WHERE id=?',[$name,$color,$id]);return $id;}return Db::run('INSERT INTO work_labels(project_id,name,color) VALUES (?,?,?)',[$project,$name,$color]);}
    public static function saveGrouping(int $project,string $type,array $data,?int $id=null):int{
        $p=self::project($project);if(!in_array($type,['cycle','module'],true))throw new InvalidArgumentException('Choose cycle or module.');$table=$type==='cycle'?'work_cycles':'work_modules';$name=self::text($data['name']??'',160,true);$description=self::text($data['description']??'',5000);$status=$data['status']??'planned';if(!in_array($status,$type==='cycle'?['planned','active','completed']:['planned','in_progress','paused','completed','cancelled'],true))throw new InvalidArgumentException('Choose a valid status.');if($id)self::scoped($table,$project,$id);
        if($type==='cycle'){$start=self::date($data['starts_on']??'');$end=self::date($data['ends_on']??'');if(($start===null)!==($end===null)||($start&&$end<$start))throw new InvalidArgumentException('Set both cycle dates, with the end on or after its start.');if($id)Db::run('UPDATE work_cycles SET name=?,description=?,starts_on=?,ends_on=?,status=? WHERE id=?',[$name,$description,$start,$end,$status,$id]);else $id=Db::run('INSERT INTO work_cycles(project_id,name,description,starts_on,ends_on,status) VALUES (?,?,?,?,?,?)',[$project,$name,$description,$start,$end,$status]);}
        else{$lead=optional_id($data['lead_id']??'');if($lead)self::person((int)$p['workspace_id'],$lead,true);$target=self::date($data['target_date']??'');if($id)Db::run('UPDATE work_modules SET name=?,description=?,lead_id=?,target_date=?,status=? WHERE id=?',[$name,$description,$lead,$target,$status,$id]);else $id=Db::run('INSERT INTO work_modules(project_id,name,description,lead_id,target_date,status) VALUES (?,?,?,?,?,?)',[$project,$name,$description,$lead,$target,$status]);}self::log($project,null,$type.'.saved',$name);self::snapshot($project);return $id;
    }
    public static function groupings(int $project,string $type):array{self::project($project);$table=$type==='cycle'?'work_cycles':($type==='module'?'work_modules':throw new InvalidArgumentException('Choose cycles or modules.'));$fk=$type.'_id';return Db::all("SELECT g.*,(SELECT COUNT(*) FROM work_issues i WHERE i.$fk=g.id AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted') total,(SELECT COUNT(*) FROM work_issues i JOIN work_states s ON s.id=i.state_id WHERE i.$fk=g.id AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted' AND s.state_group='completed') completed FROM $table g WHERE g.project_id=? ORDER BY g.id DESC",[$project]);}
    public static function log(int $project,?int $issue,string $event,string $detail):void{$p=self::project($project);Db::run('INSERT INTO work_activity(project_id,issue_id,actor_id,event,detail,day) VALUES (?,?,?,?,?,?)',[$project,$issue,self::self((int)$p['workspace_id']),$event,$detail,date('Y-m-d')]);}
    public static function activity(int $project):array{self::project($project);return Db::all('SELECT a.*,p.name actor_name FROM work_activity a JOIN work_people p ON p.id=a.actor_id WHERE a.project_id=? ORDER BY a.id DESC LIMIT 100',[$project]);}
    public static function snapshot(int $project):void{self::project($project);$cycles=[0,...array_map(fn($r)=>(int)$r['id'],Db::all('SELECT id FROM work_cycles WHERE project_id=?',[$project]))];foreach($cycles as $cycle){$where="i.project_id=? AND i.deleted_at IS NULL AND i.archived_at IS NULL AND i.intake_status='accepted'";$params=[$project];if($cycle){$where.=' AND i.cycle_id=?';$params[]=$cycle;}$row=Db::one("SELECT COUNT(*) total,COALESCE(SUM(s.state_group='completed'),0) completed,COALESCE(SUM(i.estimate),0) points FROM work_issues i JOIN work_states s ON s.id=i.state_id WHERE $where",$params);Db::run('INSERT INTO work_snapshots(project_id,cycle_id,day,total,completed,points) VALUES (?,?,?,?,?,?) ON CONFLICT(project_id,cycle_id,day) DO UPDATE SET total=excluded.total,completed=excluded.completed,points=excluded.points',[$project,$cycle,date('Y-m-d'),$row['total'],$row['completed'],$row['points']]);}}
    public static function savePage(int $project,array $data,?int $id=null):int{self::project($project);$title=self::text($data['title']??'',200,true);$body=self::text($data['body']??'',60000);$pinned=($data['pinned']??'0')==='1'?1:0;return Db::tx(function()use($project,$title,$body,$pinned,$id,$data){if($id){$page=self::scoped('work_pages',$project,$id);if($page['deleted_at']!==null||int_range($data['version']??'',1,PHP_INT_MAX)!==(int)$page['version'])throw new InvalidArgumentException('This page changed. Reload before saving.');$version=(int)$page['version']+1;Db::run('UPDATE work_pages SET title=?,body=?,pinned=?,version=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$title,$body,$pinned,$version,$id]);}else{$id=Db::run('INSERT INTO work_pages(project_id,title,body,pinned) VALUES (?,?,?,?)',[$project,$title,$body,$pinned]);$version=1;}Db::run('INSERT INTO work_page_versions(page_id,version,title,body) VALUES (?,?,?,?)',[$id,$version,$title,$body]);self::log($project,null,'page.saved',$title);return $id;});}
    public static function favorite(int $workspace,string $entity,int $id,bool $on):void{if($entity==='project'){$p=self::project($id);if((int)$p['workspace_id']!==$workspace)throw new InvalidArgumentException('Choose a project from this workspace.');}elseif($entity==='issue'){$issue=WorkIssueService::get($id);$p=self::project((int)$issue['project_id']);if((int)$p['workspace_id']!==$workspace)throw new InvalidArgumentException('Choose an issue from this workspace.');}else throw new InvalidArgumentException('Choose a project or issue to favourite.');if($on)Db::run('INSERT OR IGNORE INTO work_favorites(workspace_id,entity,entity_id) VALUES (?,?,?)',[$workspace,$entity,$id]);else Db::run('DELETE FROM work_favorites WHERE workspace_id=? AND entity=? AND entity_id=?',[$workspace,$entity,$id]);}
}
